from pathlib import Path
import json,base64
O=Path(__file__).resolve().parent
D=json.loads((O/'samples.json').read_text());D['images']={p.name:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for p in sorted((O/'originals').glob('*.png'))}
html=r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Puente · acabados</title><style>
*{box-sizing:border-box}body{margin:0;background:#101820;color:#edf2f8;font:16px/1.5 system-ui}header,main{max-width:1500px;margin:auto;padding:24px}h1{font-size:42px;margin:8px 0}p{max-width:1000px;color:#b8c6d7}button,select{font:inherit;background:#243549;color:#edf2f8;border:1px solid #60758e;border-radius:8px;padding:10px;min-height:44px;cursor:pointer}button:focus-visible,select:focus-visible{outline:3px solid #ffd59a}button[aria-pressed=true]{background:#b9d9ff;color:#132135}.tools{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{min-width:0;border:1px solid #46576c;border-radius:12px;overflow:hidden;background:#192530}.info{padding:14px}.info h2{margin:0;font-size:22px}.info p{font-size:14px;min-height:42px}.shot{width:100%;display:block;cursor:zoom-in;background:#131d28;object-fit:contain;max-height:510px}aside{padding:18px;background:#233447;border-radius:12px;margin:18px 0}.note{font-size:14px}dialog{width:min(1500px,97vw);max-height:95vh;background:#111b25;color:#edf2f8;border:1px solid #7890aa;border-radius:12px}dialog::backdrop{background:#000d}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.pair img,.single img{width:100%;display:block}.modaltools{position:sticky;top:0;background:#111b25;padding:8px}#summary{font-size:20px;font-weight:700}a{color:#bddcff}@media(max-width:650px){header,main{padding:16px}h1{font-size:32px}.grid{grid-template-columns:1fr}.pair{gap:4px}}
</style><header><small>SPOTLIGHT NEXT · LABORATORIO COMPOSE</small><h1>Puente. Ahora, sus acabados.</h1><p>La composición que te gustó, con ocho paletas, cinco letras, tres espaciados y tres superficies. Capturas reales del prototipo: sin filtros CSS ni imágenes generadas.</p><aside>En cada comparación cambia <b>un solo eje</b>. Base común: C01 Grafito + T01 Geist + E02 Equilibrado + A02 Suave. Elegir piezas crea una lista de preferencias; <b>todavía no muestra la mezcla renderizada</b>.</aside></header><main>
<div class="tools"><label>Explorar <select id="group"><option value="color">Paletas · 8</option><option value="type">Tipografías · 5</option><option value="space">Espaciado · 3</option><option value="material">Superficies · 3</option></select></label><label>Dispositivo <select id="device"><option value="tablet">Tablet · 1200 × 800 dp</option><option value="phone">Teléfono · 412 × 860 dp</option></select></label><label>Tema <select id="theme"><option value="dark">Oscuro</option><option value="light">Claro</option></select></label><label>Escena <select id="scene"><option value="acciones">Aplicación y acciones</option><option value="contexto">Documento y contexto</option></select></label></div><p id="conditions" class="note"></p><div class="tools"><label>A <select id="left"></select></label><label>B <select id="right"></select></label><button id="compare">Comparar lado a lado</button><button id="reference">Ver Puente anterior · oscuro</button></div><section id="grid" class="grid"></section>
<aside><h2>Mi combinación para probar después</h2><div id="summary"></div><p>No se integra nada. La combinación elegida debe renderizarse y revisarse antes de aprobar su implementación.</p><button id="export">Guardar elección JSON</button><p class="note">Podés decirme, por ejemplo: C05 + T02 + E02 + A01.</p></aside><h2>Cómo lo miraría yo</h2><p>C03 Niebla ofrece calma; C05 Cobre da más personalidad; C07 Marfil resulta interesante en claro. Empezaría con Geist o Inter y espaciado Equilibrado. Serif y Mono son alternativas deliberadamente más arriesgadas: ocupan distinto ancho y cambian mucho el carácter.</p><h2>Alcance real</h2><p>86 capturas nuevas + 2 referencias anteriores exactas. Robolectric API 33, datos ficticios y una sola ventana Compose que representa dos superficies. No demuestra ventanas Android independientes, rendimiento físico, IME, contraste sobre otras apps ni compatibilidad con texto 200 %. El documento de ejemplo conserva Geist para no simular cambios en el archivo.</p><p>Las paletas tienen ambos temas y dos escenas. Tipografías, densidad y superficies se comparan en oscuro con acciones. Los botones del laboratorio no ejecutan aplicaciones. Focus Studio, Preview 69 y el catálogo funcional permanecen intactos.</p></main><dialog id="modal"><div class="modaltools"><button id="close">Cerrar · Escape</button><p id="caption"></p></div><div id="modalbody"></div></dialog><script>
const D=__DATA__, $=s=>document.querySelector(s), chosen={color:'C01',type:'T01',space:'E02',material:'A02'};
function current(){return D.items.filter(i=>i.group===$('#group').value)}
function src(id){return D.images[$('#device').value+'-'+id+'-'+$('#theme').value+'-'+$('#scene').value+'.png']}
function zoom(ids,ref=false){$('#caption').textContent=ref?'Referencia anterior exacta · oscuro · acciones':ids.join(' frente a ')+' · '+$('#device').selectedOptions[0].text+' · '+$('#theme').value+' · '+$('#scene').value;$('#modalbody').className=ids.length>1?'pair':'single';$('#modalbody').innerHTML=ids.map(id=>'<img alt="Captura Compose '+id+'" src="'+(ref?D.images[$('#device').value+'-R00-dark-acciones.png']:src(id))+'">').join('');$('#modal').showModal()}
function summary(){$('#summary').textContent=Object.values(chosen).join(' + ')}
function render(){const palette=$('#group').value==='color';$('#theme').disabled=!palette;$('#scene').disabled=!palette;if(!palette){$('#theme').value='dark';$('#scene').value='acciones'}$('#conditions').textContent=palette?'Sólo cambia la paleta. Mismos datos, dimensiones, Geist, espaciado Equilibrado y superficie Suave.':'Sólo cambia este eje. Grafito · oscuro · acciones; los controles de tema y escena quedan desactivados.';const list=current();for(const s of ['#left','#right'])$(s).innerHTML=list.map(i=>'<option value="'+i.id+'">'+i.id+' · '+i.name+'</option>').join('');$('#right').selectedIndex=1;$('#grid').innerHTML=list.map(i=>'<article class="card"><div class="info"><h2>'+i.id+' · '+i.name+'</h2><p>'+i.note+'</p><button data-pick="'+i.id+'" aria-pressed="'+(chosen[i.group]===i.id)+'">Elegir '+i.id+'</button></div><img class="shot" alt="Captura Compose '+i.id+'" data-zoom="'+i.id+'" src="'+src(i.id)+'"></article>').join('');document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>zoom([b.dataset.zoom]));document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{chosen[$('#group').value]=b.dataset.pick;summary();render()})}
for(const s of ['#group','#device','#theme','#scene'])$(s).onchange=render;$('#compare').onclick=()=>zoom([$('#left').value,$('#right').value]);$('#reference').onclick=()=>zoom(['R00'],true);$('#close').onclick=()=>$('#modal').close();$('#export').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({kind:'lab-preferences-not-rendered-combination',chosen},null,2)],{type:'application/json'}));a.download='Mi-Puente.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};summary();render();
</script></html>'''
(O/'Galeria-Puente.html').write_text(html.replace('__DATA__',json.dumps(D,ensure_ascii=False,sort_keys=True)))
